pub const DescriptorProto = struct {
    name: ?[]const u8 = null,
    field: []*FieldDescriptorProto = &.{},
    extension: []*FieldDescriptorProto = &.{},
    nested_type: []*DescriptorProto = &.{},
    enum_type: []*EnumDescriptorProto = &.{},
    extension_range: []*DescriptorProto_ExtensionRange = &.{},
    oneof_decl: []*OneofDescriptorProto = &.{},
    options: ?*MessageOptions = null,
    reserved_range: []*DescriptorProto_ReservedRange = &.{},
    reserved_name: [][]const u8 = &.{},

    pub fn decode(a: std.mem.Allocator, buf: []const u8) wire.DecodeError!*DescriptorProto {
        var r = wire.Reader.init(buf);
        return decodeReader(a, &r);
    }

    pub fn decodeReader(a: std.mem.Allocator, r: *wire.Reader) wire.DecodeError!*DescriptorProto {
        const msg = try a.create(DescriptorProto);
        msg.* = .{};
        var list_field: std.ArrayList(*FieldDescriptorProto) = .empty;
        var list_extension: std.ArrayList(*FieldDescriptorProto) = .empty;
        var list_nested_type: std.ArrayList(*DescriptorProto) = .empty;
        var list_enum_type: std.ArrayList(*EnumDescriptorProto) = .empty;
        var list_extension_range: std.ArrayList(*DescriptorProto_ExtensionRange) = .empty;
        var list_oneof_decl: std.ArrayList(*OneofDescriptorProto) = .empty;
        var list_reserved_range: std.ArrayList(*DescriptorProto_ReservedRange) = .empty;
        var list_reserved_name: std.ArrayList([]const u8) = .empty;
        while (try r.next()) |tag| {
            switch (tag.field) {
                1 => {
                    msg.name = try r.readBytes();
                },
                2 => {
                    var sub = try r.subReader();
                    try list_field.append(a, try FieldDescriptorProto.decodeReader(a, &sub));
                },
                6 => {
                    var sub = try r.subReader();
                    try list_extension.append(a, try FieldDescriptorProto.decodeReader(a, &sub));
                },
                3 => {
                    var sub = try r.subReader();
                    try list_nested_type.append(a, try DescriptorProto.decodeReader(a, &sub));
                },
                4 => {
                    var sub = try r.subReader();
                    try list_enum_type.append(a, try EnumDescriptorProto.decodeReader(a, &sub));
                },
                5 => {
                    var sub = try r.subReader();
                    try list_extension_range.append(a, try DescriptorProto_ExtensionRange.decodeReader(a, &sub));
                },
                8 => {
                    var sub = try r.subReader();
                    try list_oneof_decl.append(a, try OneofDescriptorProto.decodeReader(a, &sub));
                },
                7 => {
                    var sub = try r.subReader();
                    msg.options = try MessageOptions.decodeReader(a, &sub);
                },
                9 => {
                    var sub = try r.subReader();
                    try list_reserved_range.append(a, try DescriptorProto_ReservedRange.decodeReader(a, &sub));
                },
                10 => {
                    try list_reserved_name.append(a, try r.readBytes());
                },
                else => try r.skip(tag.wire),
            }
